import { getLlm, type ChatMessage } from "./llm";
import { buildContextBlock, GROUNDED_SYSTEM_PROMPT } from "./prompts";
import { retrieve, type RetrievedChunk } from "./retrieve";

export type SourceRef = {
  /** Citation label used in the answer text, e.g. "S1". */
  label: string;
  chunkId: string;
  documentId: string;
  documentSlug: string;
  documentTitle: string;
  version: number;
  headingPath: string;
  excerpt: string;
  /** True when the generated answer explicitly cites this source. */
  cited: boolean;
};

export type KnowledgeAnswer = {
  /**
   * llm        — generated by the LLM from retrieved passages (grounded, cited)
   * extractive — no LLM available/failed: verbatim passages from the documents
   * no_answer  — nothing relevant in the knowledge base
   * error      — retrieval itself failed; nothing is claimed
   */
  mode: "llm" | "extractive" | "no_answer" | "error";
  /** Retrieval confidence (see retrieve.ts). Absent when retrieval failed. */
  confidence?: "high" | "low" | "none";
  text: string;
  sources: SourceRef[];
  notice?: string;
  telemetry: {
    retrievalMs?: number;
    generationMs?: number;
    sourceChunkIds: string[];
    promptTokens?: number;
    completionTokens?: number;
    provider: string;
    error?: string;
  };
};

const NO_ANSWER_TEXT =
  "I couldn't find that in Slotly's documentation, so I don't want to guess. You can ask about our services, opening hours, booking rules, or cancellation and rescheduling policy — or contact the studio team for anything else.";

function excerpt(chunk: RetrievedChunk, max = 420): string {
  const body = chunk.headingPath && chunk.content.startsWith(chunk.headingPath)
    ? chunk.content.slice(chunk.headingPath.length).trim()
    : chunk.content;
  return body.length > max ? `${body.slice(0, max).replace(/\s+\S*$/, "")}…` : body;
}

function toSources(chunks: RetrievedChunk[], cited: Set<number>): SourceRef[] {
  return chunks.map((c, i) => ({
    label: `S${i + 1}`,
    chunkId: c.chunkId,
    documentId: c.documentId,
    documentSlug: c.documentSlug,
    documentTitle: c.documentTitle,
    version: c.version,
    headingPath: c.headingPath,
    excerpt: excerpt(c),
    cited: cited.has(i + 1),
  }));
}

/**
 * Keeps only citations that refer to passages we actually supplied. Unknown
 * labels (e.g. a hallucinated "[S9]") are stripped from the text.
 */
export function reconcileCitations(text: string, sourceCount: number): { text: string; cited: Set<number> } {
  const cited = new Set<number>();
  const cleaned = text.replace(/\[S(\d+)\]/g, (_m, n: string) => {
    const i = Number(n);
    if (i >= 1 && i <= sourceCount) {
      cited.add(i);
      return `[S${i}]`;
    }
    return "";
  });
  return { text: cleaned.replace(/[ \t]{2,}/g, " ").trim(), cited };
}

/** Retrieval-augmented answer to a knowledge question (policies, hours, services, FAQ). */
export async function answerFromKnowledge(
  question: string,
  history: { role: "user" | "assistant"; content: string }[] = [],
  opts: { categories?: string[] } = {},
): Promise<KnowledgeAnswer> {
  const llm = getLlm();
  const provider = llm ? `${llm.name}:${llm.model}` : "none";

  let retrieval;
  try {
    retrieval = await retrieve(question, { categories: opts.categories });
  } catch (error) {
    return {
      mode: "error",
      text: "I can't search Slotly's knowledge base right now, so I can't give you a reliable answer. Booking and managing appointments still work normally — please try your question again in a moment.",
      sources: [],
      telemetry: { sourceChunkIds: [], provider, error: error instanceof Error ? error.message : "retrieval failed" },
    };
  }

  const retrievalMs = retrieval.embeddingMs + retrieval.searchMs + retrieval.rerankMs;
  const confidence = retrieval.confidence;
  const relevant = retrieval.relevant;
  const sourceChunkIds = relevant.map((c) => c.chunkId);

  if (relevant.length === 0) {
    return { mode: "no_answer", confidence: "none", text: NO_ANSWER_TEXT, sources: [], telemetry: { retrievalMs, sourceChunkIds, provider } };
  }

  if (llm) {
    const messages: ChatMessage[] = [
      { role: "system", content: GROUNDED_SYSTEM_PROMPT },
      ...history.slice(-4).map((h) => ({ role: h.role, content: h.content.slice(0, 1500) }) as ChatMessage),
      {
        role: "user",
        content: `${buildContextBlock(relevant)}${
          confidence === "low" ? "\n\nNote: these passages are only loosely related to the question. If they do not answer it, say so plainly." : ""
        }\n\nQuestion: ${retrieval.query}`,
      },
    ];
    const t0 = performance.now();
    try {
      const result = await llm.complete(messages, { maxTokens: 500, temperature: 0.1 });
      const generationMs = Math.round(performance.now() - t0);
      const { text, cited } = reconcileCitations(result.text, relevant.length);
      return {
        mode: "llm",
        confidence,
        text,
        sources: toSources(relevant, cited),
        telemetry: {
          retrievalMs,
          generationMs,
          sourceChunkIds,
          provider,
          promptTokens: result.usage?.promptTokens,
          completionTokens: result.usage?.completionTokens,
        },
      };
    } catch (error) {
      const generationMs = Math.round(performance.now() - t0);
      return {
        ...extractive(relevant, confidence),
        notice: "The AI writer is unavailable right now, so here are the most relevant passages from our documentation, quoted directly.",
        telemetry: { retrievalMs, generationMs, sourceChunkIds, provider, error: error instanceof Error ? error.message : "generation failed" },
      };
    }
  }

  return { ...extractive(relevant, confidence), telemetry: { retrievalMs, sourceChunkIds, provider } };
}

/** Verbatim passages, clearly labelled — never presented as generated prose. */
function extractive(relevant: RetrievedChunk[], confidence: KnowledgeAnswer["confidence"]): Pick<KnowledgeAnswer, "mode" | "text" | "sources" | "confidence"> {
  const top = relevant.slice(0, 3);
  const lead = top[0];
  return {
    mode: "extractive",
    confidence,
    text:
      confidence === "high"
        ? `Here's what Slotly's documentation says [S1]:\n\n${excerpt(lead, 600)}`
        : `I couldn't find a direct answer in Slotly's documentation. The closest passage is [S1]:\n\n${excerpt(lead, 600)}\n\nIf that doesn't cover your question, please contact the studio.`,
    sources: toSources(top, new Set([1])),
  };
}
